#include "robotblocks_runtime.h"


void fn_saludar();
void fn_saludar() {
    Serial.println(String("\302\241Hola!"));
}

static void proceso_1() {
    static RbProcessState s;
    PT_BEGIN(s);
    while (true) {
        fn_saludar();
        PT_SLEEP(s, 500);
        fn_saludar();
        PT_SLEEP(s, 2000);
        PT_YIELD(s);
    }
    PT_END(s);
}

void setup() { Serial.begin(115200); }

void loop() { rb_error_repeat(); proceso_1(); }
